from pathlib import Path; import black
for name in ['pylint/lint/expand_modules.py', 'tests/lint/unittest_expand_modules.py']:
    path = Path(name)
    try:
        formatted = black.format_file_contents(path.read_text(), fast=False, mode=black.FileMode())
    except black.NothingChanged:
        print(name, 'already formatted')
    else:
        path.write_text(formatted)
        print(name, 'formatted')
    assert black.format_str(path.read_text(), mode=black.FileMode()) == path.read_text()

